/**
 * Regression tests for PostgreSQL identity-column sequence semantics.
 *
 * GENERATED ALWAYS AS IDENTITY must reject explicit values (unless OVERRIDING
 * SYSTEM VALUE), while GENERATED BY DEFAULT AS IDENTITY must accept them.
 * These semantics are implemented by rewriteIdentityInsertSql via the
 * _sqlvec_identity_columns sequence registry (SequenceManager), which is only
 * populated when the identity DDL is delegated to GeneratedColumnShim (not the
 * AUTOINCREMENT shortcut in IdentityColumnShim).
 */
import { describe, it, expect, beforeAll } from 'vitest';
import Database from 'better-sqlite3';
import { QueryRouter } from '../query/QueryRouter';
import { VectorMetric, VectorMode, VectorIndexType } from '../types/types-raw';

let qr: QueryRouter;
let db: Database.Database;

function makeRouter() {
  db = new Database(':memory:');
  const sm: any = {
    getAllShards: () => new Map([[0, { db, vectorIndex: null, readers: [] }] as any]),
    getShard: (n: number) => (n === 0 ? { db, vectorIndex: null, readers: [] } as any : undefined),
    execShard: async (_n: number, sql: string) => db.exec(sql),
    queryShard: (_n: number, sql: string, params?: any[]) => db.prepare(sql).all(...(params || [])),
    getShardCount: () => 1,
    getShardIdForKey: () => 0,
    getShardIds: () => [0],
    execAll: async (sql: string) => db.exec(sql),
    queryAll: async () => [],
    getStats: () => [],
    execAllBatch: async (sqls: string[]) => db.exec(sqls.join(';')),
    execBatchOnShard: async (_n: number, sqls: string[]) => db.exec(sqls.join(';')),
    rotateAllKeys: () => [{ success: true }],
  };
  const config: any = {
    enabled: true,
    dimension: 768,
    metric: VectorMetric.COSINE,
    mode: VectorMode.AUTO,
    bruteForceThreshold: 1000,
    indexType: VectorIndexType.FLAT,
    indexParams: {},
  };
  qr = new QueryRouter(sm, {} as any, config);
}

beforeAll(() => makeRouter());

describe('identity column sequence semantics', () => {
  it('rejects explicit values into GENERATED ALWAYS AS IDENTITY', async () => {
    await qr.execute('CREATE TABLE t (id INT GENERATED ALWAYS AS IDENTITY, name TEXT)');
    // PG: INSERT with an explicit value into an ALWAYS identity column must fail.
    await expect(
      qr.execute("INSERT INTO t (id, name) VALUES (99, 'explicit')"),
    ).rejects.toThrow(/always identity|cannot insert/i);
  });

  it('accepts explicit values with OVERRIDING SYSTEM VALUE on ALWAYS identity', async () => {
    await qr.execute('CREATE TABLE t2 (id INT GENERATED ALWAYS AS IDENTITY, name TEXT)');
    await qr.execute("INSERT INTO t2 (id, name) OVERRIDING SYSTEM VALUE VALUES (17, 'forced')");
    const r = await qr.execute('SELECT id, name FROM t2');
    expect(r.rows).toEqual([{ id: 17, name: 'forced' }]);
  });

  it('accepts explicit values into GENERATED BY DEFAULT AS IDENTITY', async () => {
    await qr.execute('CREATE TABLE t3 (id INT GENERATED BY DEFAULT AS IDENTITY, name TEXT)');
    await qr.execute("INSERT INTO t3 (id, name) VALUES (5, 'explicit')");
    const r = await qr.execute('SELECT id, name FROM t3');
    expect(r.rows).toEqual([{ id: 5, name: 'explicit' }]);
  });
});
